function check(input, actual, expected) {
  const [values] = input;
  if (!Array.isArray(actual) || actual.some(v => !Number.isInteger(v))) return false;
  // A finished list has no zero-sum run left, so all of its prefix sums (starting from 0) differ.
  const prefixes = new Set([0]);
  let total = 0;
  for (const v of actual) {
    total += v;
    if (prefixes.has(total)) return false;
    prefixes.add(total);
  }
  // Cutting zero-sum runs never changes the sum of the whole list.
  if (total !== values.reduce((a, b) => a + b, 0)) return false;
  // The kept nodes appear in the original order and every gap between them adds up to 0, so the original
  // prefix sum just before a kept node equals the answer's prefix sum so far. Matching greedily is enough.
  let matched = 0, before = 0, kept = 0;
  for (const v of values) {
    if (matched < actual.length && before === kept && v === actual[matched]) {
      kept += v;
      matched++;
    }
    before += v;
  }
  return matched === actual.length;
}

