function validate([head]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 1000) return 'The list needs 1 to 1000 nodes.';
  if (head.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each value is an integer between -1000 and 1000.';
  return null;
}

