  const values = [];
  for (let p = head; p; p = p.next) values.push(p.val);
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < values.length && !changed; i++) {
      let sum = 0;
      for (let j = i; j < values.length; j++) {
        sum += values[j];
        if (sum === 0) { values.splice(i, j - i + 1); changed = true; break; }
      }
    }
  }
  let result = null;
  for (let i = values.length - 1; i >= 0; i--) result = new ListNode(values[i], result);
  return result;
}

