function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const top = rand() < 0.7 ? 3 : 1000;
    return [Array.from({ length: int(1, 8) }, () => int(-top, top))];
  }
  const shape = int(0, 2);
  if (shape === 0) return [Array.from({ length: 1000 }, () => int(-1000, 1000))];
  if (shape === 1) return [Array.from({ length: 1000 }, () => int(-5, 5))];
  // Mostly positive values with occasional deep negative values that cancel long runs.
  const list = [];
  while (list.length < 1000) {
    const run = [];
    for (let k = int(1, 20); k > 0 && list.length + run.length < 999; k--) run.push(int(1, 50));
    list.push(...run);
    const sum = run.reduce((a, b) => a + b, 0);
    list.push(rand() < 0.5 && sum <= 1000 ? -sum : int(-1000, 1000));
  }
  return [list.slice(0, 1000)];
}
